mapper.sql:
WHERE general_ledgers.is_approve = 1
AND general_ledgers.is_active = 1
AND general_ledger_details.customer_id IS NOT NULL
AND general_ledger_details.customer_id != ''
AND general_ledger_details.chart_account_id IN (
SELECT id FROM chart_accounts WHERE
chart_account_type_id = 2
)
AND general_ledger_details.company_id IN (
SELECT company_id FROM user_companies
WHERE user_id = #{userId}
)

    AND (
    general_ledger_details.type LIKE CONCAT('%', #{filter.searchText}, '%')
    OR general_ledgers.reference LIKE CONCAT('%', #{filter.searchText}, '%')
    OR sales_orders.so_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND general_ledgers.date >= #{filter.dateFrom}


    AND general_ledgers.date <= #{filter.dateTo}


    AND general_ledger_details.class_id = #{filter.classId}


    AND general_ledger_details.customer_id = #{filter.organizationId}


    AND general_ledger_details.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND general_ledger_details.company_id = #{filter.companyId}


    AND general_ledgers.is_adj = #{filter.adjustmentEntry}


    AND general_ledgers.is_sys = #{filter.Input}

mapper.select:
SELECT customers.id AS organizationId, customers.name AS organizationName, general_ledgers.id AS id, general_ledger_details.type AS type, general_ledgers.date AS `date`, companies.name AS companyName, general_ledgers.reference AS reference, sales_orders.so_code AS invoiceCode, (SELECT CONCAT(account_codes, ' · ', account_description) FROM chart_accounts WHERE id = general_ledger_details.chart_account_id) AS account, IF(general_ledger_details.debit > 0, general_ledger_details.debit, general_ledger_details.credit * -1) AS amount, IF(general_ledger_details.debit > 0, general_ledger_details.debit, general_ledger_details.credit * -1) AS balance FROM general_ledgers INNER JOIN general_ledger_details ON general_ledgers.id = general_ledger_details.general_ledger_id LEFT JOIN customers ON general_ledger_details.customer_id = customers.id LEFT JOIN companies ON general_ledger_details.company_id = companies.id LEFT JOIN sales_orders ON general_ledgers.sales_order_id = sales_orders.id
ORDER BY customers.name ASC, general_ledgers.date ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}
